'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

const n = Number(input[0]);
const force = Number(input[1]);
const grid = input.slice(2, 2 + n).map(row => row.split(''));

if (Number(grid[0][0]) <= force) {
  const queue = [0];
  grid[0][0] = '*';

  for (let head = 0; head < queue.length; head++) {
    const cell = queue[head];
    const r = Math.floor(cell / n);
    const c = cell % n;

    const neighbors = [];
    if (r > 0) neighbors.push(cell - n);
    if (r + 1 < n) neighbors.push(cell + n);
    if (c > 0) neighbors.push(cell - 1);
    if (c + 1 < n) neighbors.push(cell + 1);

    for (const next of neighbors) {
      const nr = Math.floor(next / n);
      const nc = next % n;
      if (grid[nr][nc] !== '*' && Number(grid[nr][nc]) <= force) {
        grid[nr][nc] = '*';
        queue.push(next);
      }
    }
  }
}

process.stdout.write(grid.map(row => row.join('')).join('\n'));
